package com.rationportal.model; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="grievances") public class Grievance { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="grievance_number",unique=true,nullable=false) private String grievanceNumber; @Column(name="applicant_name",nullable=false) private String applicantName; @Column(name="ration_card_number",nullable=false) private String rationCardNumber; @Column(nullable=false) private String category; @Column(name="contact_number",nullable=false) private String contactNumber; @Column(nullable=false) private String description; @Column(nullable=false) private String status; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @PrePersist protected void onCreate(){if(createdAt==null)createdAt=LocalDateTime.now();if(status==null)status="SUBMITTED";} public Long getId(){return id;} public String getGrievanceNumber(){return grievanceNumber;} public void setGrievanceNumber(String grievanceNumber){this.grievanceNumber=grievanceNumber;} public String getApplicantName(){return applicantName;} public void setApplicantName(String applicantName){this.applicantName=applicantName;} public String getRationCardNumber(){return rationCardNumber;} public void setRationCardNumber(String rationCardNumber){this.rationCardNumber=rationCardNumber;} public String getCategory(){return category;} public void setCategory(String category){this.category=category;} public String getContactNumber(){return contactNumber;} public void setContactNumber(String contactNumber){this.contactNumber=contactNumber;} public String getDescription(){return description;} public void setDescription(String description){this.description=description;} public String getStatus(){return status;} public void setStatus(String status){this.status=status;} public LocalDateTime getCreatedAt(){return createdAt;} }
